SourceCode.Declaration:
/// <summary>
/// Contract class for the MET Nature 30/40 report.
/// Holds the report parameters passed through the SysOperation framework.
/// Consumed by METNature3040ReportUIBuilder.
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessing(classStr(METNature3040ReportUIBuilder))
]
public class METNature3040ReportContract
{
    METNat30Number      metNat30Number;
    METNAT3040          metNat3040;
    boolean             CPI;
    TransDateTime       lastRunDateTime;
    TransDateTime       fromDate;
    TransDateTime       toDate;
    InventSiteId        site;
    Name                siteName;
    METBondNumber       bondNumber;

}

Method.Source:
/// <summary>
/// bond number parameter for the report.
/// </summary>
/// <param name = "_bondNumber">bond number</param>
/// <returns>bond number</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public METBondNumber parmBondNumber(METBondNumber _bondNumber = bondNumber)
{
    bondNumber = _bondNumber;
    return bondNumber;
}

/// <summary>
/// Gets or sets the CPI flag for the report.
/// When true, CPI-related behaviour is enabled for the report run.
/// </summary>
/// <param name = "_CPI">Flag to enable or disable CPI behaviour.</param>
/// <returns>Current value of the CPI flag.</returns>
[DataMemberAttribute, 
 SysOperationLabelAttribute(literalStr("CPI"))]
public boolean parmCPI(boolean _CPI = CPI)
{
    CPI = _CPI;
    return CPI;
}

/// <summary>
/// Gets or sets from the list of sites to include when site-specific execution is enabled.
/// The list should contain site identifiers expected by the report logic.
/// </summary>
/// <param name = "_site">List of site identifiers to run the report for.</param>
/// <returns>The current site</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public InventSiteId parmSite(InventSiteId _site = site)
{
    site = _site;
    return site;
}

/// <summary>
/// Gets or sets the date/time when the report was last executed.
/// Useful for incremental or delta reporting scenarios.
/// </summary>
/// <param name = "_lastRunDateTime">Last run date/time value.</param>
/// <returns>The configured last run date/time.</returns>
[DataMemberAttribute,
 SysOperationLabelAttribute(literalStr("Last successful run"))]
public TransDateTime parmLastRunDateTime(TransDateTime _lastRunDateTime = lastRunDateTime)
{
    lastRunDateTime = _lastRunDateTime;
    return lastRunDateTime;
}

/// <summary>
/// Gets or sets the start date for the report period.
/// </summary>
/// <param name = "_fromDate">Start date of the reporting range.</param>
/// <returns>The configured from-date.</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public TransDateTime parmFromDate(TransDateTime _fromDate = fromDate)
{
    fromDate = _fromDate;
    return fromDate;
}

/// <summary>
/// Gets or sets the end date for the report period.
/// </summary>
/// <param name = "_toDate">End date of the reporting range.</param>
/// <returns>The configured to-date.</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public TransDateTime parmToDate(TransDateTime _toDate = toDate)
{
    toDate = _toDate;
    return toDate;
}

    /// <summary>
    /// Gets or sets the MET Nat30 number parameter used by the report.
    /// </summary>
    /// <param name = "_metNat30Number">Selected METNat30Number value.</param>
    /// <returns>The configured METNat30Number.</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public METNat30Number parmNat30Number(METNat30Number      _metNat30Number = metNat30Number)
    {
        metNat30Number = _metNat30Number;

        return metNat30Number;
    }

    /// <summary>
    /// Gets or sets the METNAT3040 enum value selecting the report variant.
    /// This parameter is hidden from the SysOperation UI by design.
    /// </summary>
    /// <param name = "_metNat3040">METNAT3040 enum value.</param>
    /// <returns>The configured METNAT3040 value.</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public METNAT3040 parmMETNat3040(METNAT3040      _metNat3040 = metNat3040)
    {
        metNat3040 = _metNat3040;

        return metNat3040;
    }

    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public Name parmSiteName(Name      _siteName = siteName)
    {
        siteName = _siteName;

        return siteName;
    }
